import { useEffect, useState } from "react";
import { Button, Table, Spinner, Alert } from "react-bootstrap";

function ClientsList() {
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const [showModal, setShowModal] = useState(false);
  const [editingClient, setEditingClient] = useState(null);

  const token = localStorage.getItem('token');

  const fetchClients = async () => {
    try {
      setLoading(true);
      setError(null);

      const res = await fetch('http://localhost/api/clients', {
        headers: {
          Accept: 'application/json',
          Authorization: token ? `Bearer ${token}` : undefined,
        },
      });

      if (!res.ok) throw new Error('Error al obtenir els clients');

      const data = await res.json();
      setClients(Array.isArray(data.dades) ? data.dades : []);
    } catch (err) {
      console.error(err);
      setError(err.message || 'Error al obtenir els clients');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchClients();
  }, []);

  const handleDelete = async (id) => {
    if (!token) {
      alert('No estás autenticado. Inicia sesión primero.');
      return;
    }
    if (!window.confirm('Segur que vols eliminar aquest client?')) return;
    try {
      const res = await fetch(`http://localhost/api/clients/${id}`, {
        method: 'DELETE',
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
      });

      if (res.status === 401) throw new Error('No autorizado. El token ha caducado o es inválido.');
      const data = await res.json();
      if (!res.ok || data.exit === false) throw new Error(data.missatge || 'Error eliminant client');
      setClients(clients.filter(c => c.id !== id));
      alert(data.missatge);
    } catch (err) {
      alert(err.message);
    }
  };

  const openEditModal = (client) => {
    setEditingClient({ ...client });
    setShowModal(true);
  };

  const handleChange = (e) => {
    setEditingClient({ ...editingClient, [e.target.name]: e.target.value });
  };

  const handleSave = async () => {
    if (!token) { alert('No estás autenticado. Inicia sesión primero.'); return; }
    try {
      const res = await fetch(`http://localhost/api/clients/${editingClient.id}`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
          Accept: 'application/json'
        },
        body: JSON.stringify(editingClient)
      });
      if (res.status === 401) throw new Error('No autorizado. El token ha caducado o es inválido.');
      const data = await res.json();
      if (!res.ok || data.exit === false) throw new Error(data.missatge || 'Error actualitzant client');
      setClients(clients.map(c => c.id === editingClient.id ? editingClient : c));
      setShowModal(false);
    } catch (err) {
      alert(err.message);
    }
  };

  if (loading) {
    return (
      <div className="text-center mt-5">
        <Spinner animation="border" />
      </div>
    );
  }

  if (error) {
    return (
      <Alert variant="danger" className="mt-3">
        {error}
      </Alert>
    );
  }

  if (clients.length === 0) {
    return <p className="mt-3">No hi ha clients disponibles</p>;
  }

  return (
    <div className="mt-4">
      <h2>Llista de Clients</h2>

      <Table striped bordered hover className="mt-3">
        <thead>
          <tr>
            <th>ID</th>
            <th>Nom</th>
            <th>Correu</th>
            <th>Telèfon</th>
            <th>Data de Creació</th>
            <th>Accions</th>
          </tr>
        </thead>
        <tbody>
          {clients.map((client) => (
            <tr key={client.id}>
              <td>{client.id}</td>
              <td>{client.nom}</td>
              <td>{client.correu}</td>
              <td>{client.telefon}</td>
              <td>{new Date(client.created_at).toLocaleDateString('ca-ES')}</td>
              <td>
                <Button variant="warning" size="sm" className="me-2" onClick={() => openEditModal(client)}>
                  Editar
                </Button>
                <Button variant="danger" size="sm" onClick={() => handleDelete(client.id)}>
                  Eliminar
                </Button>
              </td>
            </tr>
          ))}
        </tbody>
      </Table>

      {showModal && (
        <div className="modal show d-block" tabIndex="-1">
          <div className="modal-dialog">
            <div className="modal-content">

              <div className="modal-header">
                <h5 className="modal-title">Editar client</h5>
                <button
                  type="button"
                  className="btn-close"
                  onClick={() => setShowModal(false)}
                />
              </div>

              <div className="modal-body">
                <input
                  className="form-control mb-2"
                  name="nom"
                  value={editingClient.nom}
                  onChange={handleChange}
                  placeholder="Nom"
                />
                <input
                  className="form-control mb-2"
                  name="correu"
                  value={editingClient.correu}
                  onChange={handleChange}
                  placeholder="Correu"
                />
                <input
                  className="form-control"
                  name="telefon"
                  value={editingClient.telefon}
                  onChange={handleChange}
                  placeholder="Telèfon"
                />
              </div>

              <div className="modal-footer">
                <Button
                  variant="secondary"
                  onClick={() => setShowModal(false)}
                >
                  Cancel·lar
                </Button>
                <Button
                  variant="success"
                  onClick={handleSave}
                >
                  Guardar
                </Button>
              </div>

            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default ClientsList;
